{
  "probability": 0.34,
  "range_low": 0.28,
  "range_high": 0.40,
  "summary": [
    "Baseline anchor: US airline-holding companies have an ~5% bankruptcy rate over the relevant horizon, forming a conservative starting point.",
    "Frontier's Altman Z-score (~0.38–0.39) places it in the distress zone, elevating bankruptcy risk relative to safe peers.",
    "ULCC-specific model suggests substantial tail risk (≈45% bankruptcy probability over 24 months), raising the posterior odds of distress.",
    "Spirit dynamics and potential consolidation could mitigate Frontier's risk, yielding a calibrated posterior of 34% with notable uncertainty."
  ],
  "confidence": "low",
  "narrative": "Starting from a base-rate around 5% for airline distress, Frontier's weak fundamentals push risk upward, while sector consolidation pressures and mixed analyst signals temper it. The resulting calibrated probability is 34% with wide uncertainty about near-term outcomes, particularly regarding Spirit-related dynamics.",
  "justification": {
    "anchor": {
      "probability": 0.05,
      "basis": "Base-rate anchor: US airline holding companies' bankruptcy rate is commonly cited near 5% for multi-month horizons; Frontier sits in a distressed ULCC subset, justifying anchoring near the base rate before updates."
    },
    "factor_updates": [
      {
        "factor": "Frontier ULCC Altman Z-Score in distress zone",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Altman Z-score around 0.38–0.39 signals distress and non-trivial bankruptcy risk, pushing the probability upward."
      },
      {
        "factor": "ULCC 24-month bankruptcy probability model",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "A published model for ULCCs showing ~45% bankruptcy probability over 24 months implies tail risk that informs Frontier's risk."
      },
      {
        "factor": "Spirit bankruptcy dynamics and Frontier takeover prospects",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Spirit's distress and Frontier as potential acquirer could reduce Frontier's bankruptcy risk via consolidation and improved market dynamics."
      },
      {
        "factor": "Industry base-rate anchor for airline distress",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Baseline 5% distress risk for airline-holding companies raises Frontier's risk floor relative to the broad market."
      },
      {
        "factor": "Analyst sentiment: Deutsche Bank downgrade to Hold (Feb 2026)",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Cautious near-term outlook may temper near-term bankruptcy risk assessments."
      },
      {
        "factor": "Spirit’s planned exit from bankruptcy by mid-2026",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Expectations of Spirit exiting bankruptcy could reduce sector distress pressures on Frontier."
      }
    ],
    "synthesis_rationale": "The posterior combines a base-rate anchor with multiple, partly correlated updates. Distress signals push up probabilities, while sector consolidation and favorable near-term developments push down. The net effect yields a calibrated 0.34 with broad uncertainty; calibration accounts for potential double-counting and horizon alignment."
  }
}

{
  "probability": 0.34,
  "range_low": 0.25,
  "range_high": 0.45,
  "summary": [
    "Frontier ULCC Altman Z-score around 0.38 places it in the distress zone, implying non-trivial bankruptcy risk within the next two years.",
    "FRISK 2026 distress signal (1.3% probability of corporate failure) exceeds the long-run 1% baseline for U.S. corporates, signaling elevated sector risk.",
    "Spirit Airlines' bankruptcy dynamics could reduce Frontier's risk via potential consolidation and favorable market-share shifts.",
    "Frontier's high debt burden and weak liquidity add material financial distress risk, tempered by mixed analyst signals and regulatory considerations."
  ],
  "confidence": "low",
  "narrative": "A Bayesian-style assessment yields a 34% posterior probability that Frontier files for bankruptcy before May 1, 2026. Distress indicators lift risk, while Spirit-related restructuring and market moves offer partial offsets; substantial uncertainty remains due to correlations among factors and sector dynamics.",
  "justification": {
    "anchor": {
      "probability": 0.05,
      "basis": "Base-rate anchor for US airline-holding-company distress around 5% (prior probability before updating with Frontier-specific signals)."
    },
    "factor_updates": [
      {
        "factor": "Frontier Altman Z-Score distress indicator",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Altman Z around 0.38–0.39 places Frontier in distress territory, elevating bankruptcy risk relative to peers."
      },
      {
        "factor": "FRISK Stress Index (2026 distress vs baseline)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "FRISK project 1.3% failure probability vs 1% baseline, signaling elevated systemic distress in the airline sector."
      },
      {
        "factor": "Spirit bankruptcy dynamics and Frontier takeover prospects",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Spirit’s bankruptcy and Frontier’s potential acquisition could improve sector structure and reduce Frontier’s standalone risk."
      },
      {
        "factor": "Frontier’s high debt burden and weak liquidity",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Debt load and liquidity constraints raise distress risk and potential default probability."
      },
      {
        "factor": "Analyst sentiment: Deutsche Bank downgrade to Hold",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Cautious near-term outlook from downgrade tempers some near-term bankruptcy risk signals."
      }
    ],
    "synthesis_rationale": "The 0.34 posterior results from combining multiple partly correlated distress signals that push probability up from a 5% base-rate, while mitigants from Spirit-related dynamics and cautious analyst sentiment pull probability down. Given correlations among factors (e.g., sector distress and Altman Z) and limited independent evidence, the posterior is calibrated to a mid-single-digit-to-low-teens percentage uplift within the target window, here 34%, with a wide uncertainty range."
  }
}

